?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solicitudes de usuarios | Administración</title><link rel="stylesheet" href="../assets/style.css"><link rel="stylesheet" href="../assets/admin.css"><link rel="stylesheet" href="../assets/account-registration.css"><?php require __DIR__.'/_theme.php'; ?></head><body class="portal-admin"><?php require __DIR__.'/_navigation.php';?><main class="wrap admin-page"><h1>Solicitudes de usuarios</h1><p>Sugerencias, peticiones, quejas y reclamos. Guardar una nota no envía un correo: responde mediante el canal del equipo y registra aquí la atención.</p><?php if($error):?><p role="alert"><?=esc($error)?></p><?php endif;?><?php if(!$requests):?><p>No hay solicitudes registradas.</p><?php endif;?><?php foreach($requests as $row):?><section class="account-portal-card"><h2><?=esc(PublicRequestService::TYPES[$row['request_type']]??$row['request_type'])?> · <?=esc($row['reference'])?></h2><p><?=esc($row['name'])?> · <?=esc($row['email'])?> · <?=esc($row['created_at'])?></p><p><?=nl2br(esc($row['message']))?></p><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=esc($row['id'])?>"><label>Estado<select name="status"><?php foreach(['pending'=>'Pendiente','in_review'=>'En atención','resolved'=>'Atendida'] as $status=>$label):?><option value="<?=esc($status)?>" <?=$row['status']===$status?'selected':''?>><?=esc($label)?></option><?php endforeach;?></select></label><label>Nota interna de atención<textarea name="response_note" maxlength="10000"><?=esc($row['response_note'])?></textarea></label><button class="pill">Guardar revisión</button></form></section><?php endforeach;?></main></body></html>
